{
  "name": "@yeyuan98/opencode-bioresearcher-plugin",
  "version": "1.7.2",
  "description": "OpenCode plugin that adds a bioresearcher agent",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "type": "module",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "scripts": {
    "prebuild": "node -e \"const p=require('./package.json');require('fs').writeFileSync('src/version.ts','export const PLUGIN_VERSION = \\\"'+p.version+'\\\"\\n');const m=require('fs').readFileSync('node_modules/marked/lib/marked.umd.js','utf-8');require('fs').writeFileSync('src/tools/misc/marked-bundle.ts','export const MARKED_BUNDLE='+JSON.stringify(m)+'\\n')\"",
    "build": "npm run prebuild && node -e \"const p=require('path');const fs=require('fs');fs.mkdirSync(p.join('dist','vendor'),{recursive:true});fs.cpSync(p.join('src','vendor','xlsx.d.mts'),p.join('dist','vendor','xlsx.d.mts'))\" && esbuild node_modules/xlsx/xlsx.mjs --bundle --format=esm --outfile=dist/vendor/xlsx.mjs && tsc && node -e \"const fs=require('fs');fs.rmSync('dist/skills',{recursive:true,force:true});fs.cpSync('skills','dist/skills',{recursive:true})\"",
    "typecheck": "npm run prebuild && tsc --noEmit"
  },
  "keywords": [
    "opencode",
    "plugin",
    "bioresearch",
    "biomcp",
    "agent"
  ],
  "author": "Ye Yuan",
  "license": "CC-BY-NC-ND-4.0",
  "files": [
    "dist/",
    "LICENSE",
    "README.md"
  ],
  "dependencies": {
    "@opencode-ai/plugin": "^1.14.0",
    "fast-xml-parser": "^5.3.5",
    "mongodb": "^7.1.0",
    "mysql2": "^3.18.2",
    "xdg-basedir": "^5.1.0",
    "zod": "4.1.8"
  },
  "devDependencies": {
    "@types/bun": "^1.2.0",
    "@types/node": "^20.0.0",
    "esbuild": "^0.25.0",
    "marked": "^18.0.3",
    "typescript": "^5.9.3",
    "xlsx": "https://cdn.sheetjs.com/xlsx-0.20.3/xlsx-0.20.3.tgz"
  },
  "engines": {
    "opencode": ">=1.4.0"
  }
}
